/**
 * The "made by" badge for client-site footers. One source for the React preview
 * (Badge.jsx) and the copy-paste embed files generated by scripts/brand.mjs, so
 * they can never drift apart.
 *
 * The mini Chip's line work uses currentColor, so the badge picks up the colour
 * of whatever footer it sits in. Body and face stay fixed so Chip is always Chip.
 */
import { mini } from './sprite.js';

export const BADGE_COLORS = {
  K: 'currentColor',
  M: 'currentColor',
  L: '#fffdf6',
  S: '#e6e0cf',
  H: '#ffffff',
  F: '#0b0d11',
  D: '#c7ff58',
  P: '#ff69bd',
};

/** One <path> per colour keeps the embed snippet small. */
const rects = (runs) => {
  const by = {};
  runs.forEach((r) => {
    (by[r.c] = by[r.c] || []).push(`M${r.x} ${r.y}h${r.w}v1h-${r.w}z`);
  });
  return Object.entries(by)
    .map(([c, d]) => `<path fill="${BADGE_COLORS[c]}" d="${d.join('')}"/>`)
    .join('');
};

/** The animated mini Chip as an SVG string. */
export const badgeChipSvg = () =>
  `<svg class="tcs-chip" viewBox="0 0 16 16" width="24" height="24" shape-rendering="crispEdges" aria-hidden="true" focusable="false">` +
  `<g class="tcs-fig">` +
  `<g>${rects(mini.legs)}</g>` +
  `<g>${rects(mini.body)}</g>` +
  `<g class="tcs-wave">${rects(mini.armsWave)}</g>` +
  `<g class="tcs-open">${rects(mini.face)}</g>` +
  `<g class="tcs-shut">${rects(mini.blink)}</g>` +
  `</g></svg>`;

export const BADGE_CSS = `
.tcs-badge{position:relative;display:inline-flex;align-items:center;gap:.55em;color:inherit;font:inherit;font-size:12px;line-height:1.15;text-decoration:none;opacity:.8;transition:opacity .2s}
.tcs-badge:hover,.tcs-badge:focus-visible{opacity:1}
.tcs-badge .tcs-chip{width:24px;height:24px;flex:none;overflow:visible}
.tcs-badge .tcs-text{display:flex;flex-direction:column}
.tcs-badge small{font-size:.78em;letter-spacing:.08em;text-transform:uppercase;opacity:.75}
.tcs-badge b{font-weight:700;letter-spacing:.01em}
.tcs-badge .tcs-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.tcs-badge .tcs-shut,.tcs-badge .tcs-wave{opacity:0}
@media (prefers-reduced-motion:no-preference){
.tcs-badge .tcs-open{animation:tcs-o 5.2s steps(1,end) infinite}
.tcs-badge .tcs-shut{animation:tcs-s 5.2s steps(1,end) infinite}
.tcs-badge .tcs-fig{animation:tcs-hop 9s steps(1,end) infinite}
.tcs-badge:hover .tcs-wave,.tcs-badge:focus-visible .tcs-wave{animation:tcs-w .5s steps(1,end) infinite}
}
@keyframes tcs-o{0%,100%{opacity:1}94%{opacity:0}97%{opacity:1}}
@keyframes tcs-s{0%,100%{opacity:0}94%{opacity:1}97%{opacity:0}}
@keyframes tcs-hop{0%,100%{transform:none}90%{transform:translateY(-1px)}92%{transform:translateY(-2px)}94%{transform:translateY(-1px)}96%{transform:none}}
@keyframes tcs-w{0%{opacity:1}50%{opacity:0}}
`.trim();

/** Full embed markup (badge + its CSS). `label` is the visible URL text. */
export const badgeHtml = ({ href, label }) =>
  `<a class="tcs-badge" href="${href}" target="_blank" rel="noopener">` +
  badgeChipSvg() +
  `<span class="tcs-text"><small>Website by</small><b>${label}</b></span>` +
  `<span class="tcs-sr"> (opens in a new tab)</span></a>`;
